module dial_game (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] A,\n    input wire [3:0] B,\n    output reg [6:0] result,\n    output reg done\n);\n    parameter N = 8;\n    parameter WIDTH = 4;\n    reg [WIDTH-1:0] dials [0:N-1];\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] CALC_SUM = 2'd1;\n    localparam [1:0] UPDATE = 2'd2;\n    localparam [1:0] DONE = 2'd3;\n    reg [1:0] state;\n    reg [3:0] idx;\n    reg [6:0] sum;\n    reg [3:0] a_reg;\n    reg [3:0] b_reg;\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 7'd0;\n            sum <= 7'd0;\n            idx <= 4'd0;\n            a_reg <= 4'd0;\n            b_reg <= 4'd0;\n            for (i = 0; i < N; i = i + 1) begin\n                dials[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        a_reg <= A - 4'd1;\n                        b_reg <= B - 4'd1;\n                        idx <= A - 4'd1;\n                        sum <= 7'd0;\n                        state <= CALC_SUM;\n                    end\n                end\n                CALC_SUM: begin\n                    if (idx <= b_reg) begin\n                        sum <= sum + {3'd0, dials[idx]};\n                        idx <= idx + 4'd1;\n                    end else begin\n                        result <= sum;\n                        idx <= a_reg;\n                        state <= UPDATE;\n                    end\n                end\n                UPDATE: begin\n                    if (idx <= b_reg) begin\n                        if (dials[idx] == 4'd9) dials[idx] <= 4'd0;\n                        else dials[idx] <= dials[idx] + 4'd1;\n                        idx <= idx + 4'd1;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule